   156	    if (width != 0 && psImage->numcomps != 0 &&
   157	            (width > INT_MAX / psImage->numcomps ||
   158	             height > INT_MAX / (width * psImage->numcomps * sizeof(OPJ_UINT32)))) {
   159	        opj_stream_destroy(pStream);
